args.code:
$events = $($0.events) | ForEach-Object { $_.message };
$needsWinRM = -not (Get-Service -Name 'WinRM' -ErrorAction SilentlyContinue | Where-Object {$_.Status -eq 'Running'});
$needsW32Time = -not (Get-Service -Name 'W32Time' -ErrorAction SilentlyContinue | Where-Object {$_.Status -eq 'Running'});

# If event messages suggest issues or services not running, remediate.
if($needsWinRM){
  Set-Service -Name 'WinRM' -StartupType Automatic -ErrorAction SilentlyContinue;
  Start-Service -Name 'WinRM' -ErrorAction SilentlyContinue;
}
if($needsW32Time){
  Set-Service -Name 'W32Time' -StartupType Automatic -ErrorAction SilentlyContinue;
  Start-Service -Name 'W32Time' -ErrorAction SilentlyContinue;
}

# Output post-action status for audit
Get-Service -Name 'WinRM','W32Time' | Select-Object Name,DisplayName,Status,StartType | Format-Table -AutoSize | Out-String

New-Item -ItemType Directory -Path 'C:\ProgramData\PSX\Logs' -Force | Out-Null; $log='C:\ProgramData\PSX\Logs\winrm_fix.log'; "[$(Get-Date -Format o)] Starting WinRM remediation. Prior System errors (last 50, level=Error):" | Out-File -FilePath $log -Encoding utf8 -Append; $errors=@'
$0.events
'@; $errors | Out-File -FilePath $log -Encoding utf8 -Append; "[$(Get-Date -Format o)] Attempting WinRM restart..." | Out-File -FilePath $log -Encoding utf8 -Append; try { Restart-Service -Name WinRM -Force -ErrorAction Stop; "[$(Get-Date -Format o)] Restart-Service WinRM: OK" | Out-File -FilePath $log -Encoding utf8 -Append } catch { "[$(Get-Date -Format o)] Restart-Service WinRM: FAILED - $($_.Exception.Message)" | Out-File -FilePath $log -Encoding utf8 -Append; throw }
